fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // First, ensure each special guest can get one cookie from each pile.
    if a < m || b < m {
        return false;
    }

    // Compute total cookies and total required servings without overflow.
    let total_cookies = (a as u16) + (b as u16);
    let required_cookies = (n as u16) + 2 * (m as u16);

    // Check if we have enough cookies in total to serve regular and special guests.
    total_cookies >= required_cookies
}

